using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Rendering;
namespace ROM.UI.Sprint01 {
// Opt-in menu pilot. Only cloned owned assets; no network, collisions or gameplay scene.
public sealed class RiftLivingMenuStage:MonoBehaviour {
 readonly List<Material> materials=new List<Material>();Material energy;Transform frame;Quaternion originRotation;public bool Ready{get;private set;}public Vector3 SourceArchitectureSize{get;private set;}
 public static RiftLivingMenuStage Create(Transform previewWorld,GameObject architecture,Material smoke,Material sparks,GameObject arch=null){var root=new GameObject("Rift living menu pilot");root.transform.SetParent(previewWorld,false);var stage=root.AddComponent<RiftLivingMenuStage>();stage.Build(arch?arch:architecture,smoke,sparks);if(arch){var baseObject=Instantiate(architecture,stage.transform);baseObject.name="Owned portal base below hero";var baseRenderers=baseObject.GetComponentsInChildren<Renderer>(true);var baseBounds=baseRenderers[0].bounds;foreach(var renderer in baseRenderers)baseBounds.Encapsulate(renderer.bounds);float baseScale=1.2f/Mathf.Max(.01f,baseBounds.size.y);baseObject.transform.localScale*=baseScale;baseObject.transform.localPosition=new Vector3(0,-.6f,2)-(baseBounds.center-stage.transform.position)*baseScale;stage.Layer(baseObject.transform);foreach(var c in baseObject.GetComponentsInChildren<Collider>(true))Destroy(c);}return stage;}
 Material Instance(Material source){var m=new Material(source){hideFlags=HideFlags.DontSave};materials.Add(m);return m;}
 void Layer(Transform root){foreach(var t in root.GetComponentsInChildren<Transform>(true))t.gameObject.layer=RiftModelView.PreviewLayer;}
 void Build(GameObject architecture,Material smoke,Material sparks){
  if(!architecture)return;frame=Instantiate(architecture,transform).transform;frame.name="Owned Eternal Temple portal architecture";Layer(frame);foreach(var c in frame.GetComponentsInChildren<Collider>(true))Destroy(c);foreach(var r in frame.GetComponentsInChildren<Rigidbody>(true))Destroy(r);foreach(var lod in frame.GetComponentsInChildren<LODGroup>(true))lod.ForceLOD(0);
  var renderers=frame.GetComponentsInChildren<Renderer>(true);var bounds=renderers[0].bounds;foreach(var r in renderers)bounds.Encapsulate(r.bounds);SourceArchitectureSize=bounds.size;float scale=5.5f/Mathf.Max(.01f,bounds.size.y);frame.localScale*=scale;var offset=bounds.center-previewWorldOrigin(frame);frame.localPosition=new Vector3(-2.7f,-.6f,3.8f)-offset*scale+Vector3.up*bounds.size.y*scale*.5f;
  foreach(var r in renderers){var source=r.sharedMaterials;var copies=new Material[source.Length];for(int i=0;i<source.Length;i++){copies[i]=Instance(source[i]);if(copies[i].HasProperty("_BaseColor")){var c=copies[i].GetColor("_BaseColor");copies[i].SetColor("_BaseColor",c*new Color(.48f,.52f,.65f,1));}}r.sharedMaterials=copies;r.shadowCastingMode=ShadowCastingMode.Off;}
  var opposite=Instantiate(frame.gameObject,transform).transform;opposite.name="Owned portal right column";opposite.localPosition+=Vector3.right*5.6f;foreach(var c in opposite.GetComponentsInChildren<Collider>(true))Destroy(c);foreach(var r in opposite.GetComponentsInChildren<Rigidbody>(true))Destroy(r);
  var shader=Shader.Find("ROM/Menu/Living Rift");if(!shader)return;energy=new Material(shader){hideFlags=HideFlags.DontSave};materials.Add(energy);var plane=GameObject.CreatePrimitive(PrimitiveType.Quad);plane.name="Animated Rift energy surface";plane.transform.SetParent(transform,false);plane.transform.localPosition=new Vector3(.35f,1.6f,3.95f);plane.transform.localScale=new Vector3(3.1f,4.0f,1);Destroy(plane.GetComponent<Collider>());plane.GetComponent<MeshRenderer>().sharedMaterial=energy;plane.GetComponent<MeshRenderer>().shadowCastingMode=ShadowCastingMode.Off;
  var rim=new GameObject("Scoped violet portal fill");rim.transform.SetParent(transform,false);rim.transform.localPosition=new Vector3(.5f,1.9f,.65f);var light=rim.AddComponent<Light>();light.type=LightType.Point;light.color=new Color(.49f,.25f,1);light.intensity=2;light.range=4;light.shadows=LightShadows.None;
  if(smoke)Particles("Soft portal mist",smoke,new Color(.5f,.32f,.8f,.22f),.7f,1.1f,2,12);
  if(sparks)Particles("Warm Rift embers",sparks,new Color(1,.8f,.5f,.55f),.015f,.035f,5,28);
  Layer(transform);originRotation=frame.localRotation;Ready=true;
 }
 static Vector3 previewWorldOrigin(Transform t)=>t.parent.position;
 void Particles(string name,Material source,Color tint,float minSize,float maxSize,float rate,int maximum){var go=new GameObject(name);go.transform.SetParent(transform,false);go.transform.localPosition=new Vector3(.4f,1.5f,.9f);var ps=go.AddComponent<ParticleSystem>();ps.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);var main=ps.main;main.loop=true;main.playOnAwake=false;main.useUnscaledTime=true;main.startLifetime=new ParticleSystem.MinMaxCurve(3,6);main.startSpeed=new ParticleSystem.MinMaxCurve(.04f,.16f);main.startSize=new ParticleSystem.MinMaxCurve(minSize,maxSize);main.startColor=tint;main.maxParticles=maximum;main.simulationSpace=ParticleSystemSimulationSpace.Local;var emission=ps.emission;emission.rateOverTime=rate;var shape=ps.shape;shape.shapeType=ParticleSystemShapeType.Box;shape.scale=new Vector3(2.1f,2.5f,.2f);var fade=ps.colorOverLifetime;fade.enabled=true;var gradient=new Gradient();gradient.SetKeys(new[]{new GradientColorKey(Color.white,0),new GradientColorKey(Color.white,1)},new[]{new GradientAlphaKey(0,0),new GradientAlphaKey(1,.2f),new GradientAlphaKey(0,1)});fade.color=gradient;var renderer=ps.GetComponent<ParticleSystemRenderer>();var material=Instance(source);if(maxSize<.1f){var transparentShader=Shader.Find("ROM/Menu/Transparent embers");if(transparentShader){var ownedTexture=source.GetTexture("_BaseMap");material.shader=transparentShader;material.SetTexture("_BaseMap",ownedTexture);}}renderer.sharedMaterial=material;renderer.shadowCastingMode=ShadowCastingMode.Off;renderer.receiveShadows=false;ps.Play();}
 void Update(){if(!Ready)return;energy.SetFloat("_FlowTime",Time.unscaledTime);frame.localRotation=originRotation*Quaternion.Euler(0,Mathf.Sin(Time.unscaledTime*.18f)*.45f,0);}
 void OnDestroy(){foreach(var m in materials)if(m)Destroy(m);}
}
}
